-- Generated by scripts/sync_dbt.py. Edit canonical sql/ source.
-- One first exposure per user and transition; next-stage outcome in same session.
WITH transitions AS (
 SELECT * FROM UNNEST([
 STRUCT(2 AS stage,'view_item' AS exposure_event,'add_to_cart' AS outcome_event),
 STRUCT(3,'add_to_cart','begin_checkout'),STRUCT(4,'begin_checkout','purchase')])
), exposures AS (
 SELECT e.session_id,t.stage,t.outcome_event,MIN(e.event_timestamp) AS exposure_ts
 FROM {{ ref('stg_events') }} e JOIN transitions t ON e.event_name=t.exposure_event
 WHERE e.session_id IS NOT NULL GROUP BY e.session_id,t.stage,t.outcome_event
), eligible AS (
 SELECT s.user_pseudo_id,s.session_id,s.session_date,x.stage,x.outcome_event,x.exposure_ts
 FROM {{ ref('int_sessions') }} s JOIN exposures x USING(session_id)
 WHERE s.session_end_date<DATE '2021-01-31'
 QUALIFY ROW_NUMBER() OVER(PARTITION BY user_pseudo_id,stage ORDER BY exposure_ts,session_id)=1
), outcomes AS (
 SELECT s.user_pseudo_id,s.stage,s.session_date,COUNT(e.event_timestamp)>0 AS converted
 FROM eligible s LEFT JOIN {{ ref('stg_events') }} e ON e.session_id=s.session_id
 AND e.event_name=s.outcome_event AND e.event_timestamp>s.exposure_ts
 GROUP BY s.user_pseudo_id,s.stage,s.session_date
)
SELECT stage,session_date AS eligibility_date,COUNT(*) AS eligible_users,COUNTIF(converted) AS converted_users
FROM outcomes GROUP BY stage,eligibility_date
